<?php require 'includes/db.php';require 'includes/helpers.php';require_login();ensure_default_categories($pdo);$msg='';if(isset($_GET['delete'])){$pdo->prepare("DELETE FROM goals WHERE id=? AND user_id=?")->execute([(int)$_GET['delete'],user_id()]);header('Location:goals.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$target=(float)$_POST['target'];$saved=(float)$_POST['saved'];$date=$_POST['target_date']?:null;if($name&&$target>0){$pdo->prepare("INSERT INTO goals(user_id,name,target,saved,target_date) VALUES(?,?,?,?,?)")->execute([user_id(),$name,$target,$saved,$date]);$msg='Savings goal added.';}}$s=$pdo->prepare("SELECT * FROM goals WHERE user_id=? ORDER BY id DESC");$s->execute([user_id()]);$goals=$s->fetchAll(PDO::FETCH_ASSOC);?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Savings Goals</title><link rel="stylesheet" href="assets/style.css"></head><body class="<?=!empty($_SESSION['dark'])?'dark':''?>"><div class="app"><aside class="sidebar"><?php include 'includes/nav.php';?></aside><main class="main"><header class="top"><div><h1>Savings Goals</h1><p>Track progress toward things you want to achieve</p></div></header><div class="panel" style="max-width:850px"><?php if($msg):?><div class="alert"><?=$msg?></div><?php endif;?><form method="post" class="formgrid"><label>Goal name<input name="name" placeholder="New phone, emergency fund..." required></label><label>Target amount<input name="target" type="number" step=".01" min=".01" required></label><label>Already saved<input name="saved" type="number" step=".01" min="0" value="0"></label><label>Target date<input name="target_date" type="date"></label><div class="full actions"><button class="btn primary">Add Goal</button></div></form></div><div class="cat-grid" style="margin-top:18px"><?php foreach($goals as $g):$pct=min(100,$g['saved']/$g['target']*100);?><div class="cat" style="display:block"><div style="display:flex;justify-content:space-between"><b><?=h($g['name'])?></b><a class="delete" href="?delete=<?=$g['id']?>" onclick="return confirm('Delete this goal?')">Delete</a></div><div class="goal"><div class="goal-top"><span>₹<?=money($g['saved'])?> saved</span><span>₹<?=money($g['target'])?></span></div><div class="bar"><span style="width:<?=$pct?>%"></span></div></div><small><?=number_format($pct,1)?>% complete<?= $g['target_date']?' · target '.date('d M Y',strtotime($g['target_date'])):''?></small></div><?php endforeach;?></div><?php if(!$goals):?><div class="empty">Create your first savings goal.</div><?php endif;?></main></div></body></html>